#!/usr/bin/env python3
"""news-image-20261120 entry: write the day's news image to /output.

The image is a newspaper front page ("THE WORLD") summing up the
world news of Friday 20 November 2026: Cyclone Akvan's landfall in
Odisha, COP31 closing in Antalya, Prabowo meeting Xi in Shenzhen,
the Hunger Games film opening, day two of the New Zealand v India
Test, World Children's Day, Saturn beside the Moon, and Canada's
tariff wait. It was drawn with PIL by the build script (build.py)
kept beside this file, and embedded here as base64 so this program
needs no network and no other file.

Standard library only. Reads MAKEFUN_OUTPUT_DIR (default /output)
and writes entry.png there. Deterministic: the same bytes every run.
"""

import base64
import os
import sys

# The winning image (variant v1, newspaper front page), 1024x1024 PNG.
_IMAGE_B64 = ""


def main() -> int:
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(_IMAGE_B64)
    # Sanity check: the embedded bytes must be a whole PNG image.
    if not data.startswith(b"\x89PNG\r\n\x1a\n"):
        raise ValueError("embedded image is not a PNG")
    path = os.path.join(out_dir, "entry.png")
    with open(path, "wb") as fh:
        fh.write(data)
    return 0


if __name__ == "__main__":
    sys.exit(main())
